    media_urls,
    raw_text,
    resultado,
    favorito
  ) VALUES (
    'bded734b-15c0-4db3-851b-5ad763ee33c8',
    '[SwipeRadar] Divine Script (discount) (Espiritualidade)',
    'SwipeRadar',
    'Meta Ads / Web',
    'vsl',
    'The 12-Word Divine Script / Comando verbal bíblico de alinhamento com a Providência Divina',
    'Espiritualidade',
    ARRAY['swiperadar', 'espiritualidade', 'divine-script-discount', 'escalado', 'meta_ads']::text[],
    5,
    'ativo',
    '{"gancho":"Jesus ordena que você aceite este milagre financeiro hoje: o roteiro sagrado de 12 palavras que destrava abundância 100x mais rápido.","participacao_ativa":"Pessoas com dívidas pesadas e sentimento de estagnação que precisam de permissão teológica para receber dinheiro sem culpa.","narrativa":"Funil de alta qualificação com pré-sell interativo das \"20 sacred words\" para aquecer o tráfego frio → VSL dinâmica de 12 palavras com provas bíblicas e testemunhos gravados.","reframe":"Pedir dinheiro não é pecado; os patriarcas da Bíblia eram os homens mais ricos de sua época porque sabiam invocar o roteiro divino exato.","cta_engajamento":"Anúncios ativos no Meta Ads. Materiais e vídeos disponíveis no Drive.","cta_venda":"Divine Script livro digital + meditação guiada de 7 minutos + bônus de livramento de juros via Digistore24."}'::jsonb,
